OUT_OF_SCOPE = {
    "dev": ["Нужен повар для приготовления обедов в ресторане", "Ищу садовника для ухода за деревьями", "Требуется врач стоматолог для лечения зубов", "Нужен водитель грузовика для дальних рейсов", "Ищу сварщика для металлического забора", "Нужен бухгалтер для выплаты зарплат сотрудникам"],
    "test": ["Ищем парикмахера для окрашивания волос", "Нужен ветеринар для лечения животных", "Кто поможет с уборкой квартиры", "Требуется каменщик для строительства дома", "Ищем тренера по плаванию для детей", "Нужен юрист для представительства в суде"],
}

def records(split):
    return [dict(id=family, role=role, split=part, text=text, queries=queries)
            for family, role, part, text, queries in ROWS if part == split]

def dataset_hash():
    encoded = json.dumps({"rows": ROWS, "outOfScope": OUT_OF_SCOPE}, ensure_ascii=False, sort_keys=True).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()

def validate():
    ids = [r[0] for r in ROWS]
    assert len(ids) == len(set(ids))
    by_split = {s: records(s) for s in ["train", "dev", "test"]}
    assert all(len({r["role"] for r in values}) == 14 for values in by_split.values())
    texts = [t for r in ROWS for t in [r[3], *r[4]]]
    assert len(texts) == len(set(texts)), "Exact text leakage"
    return by_split

if __name__ == "__main__":
    print(json.dumps({"sha256": dataset_hash(), "splits": {k: {"families": len(v), "queries": sum(len(x["queries"]) for x in v)} for k, v in validate().items()}}, ensure_ascii=False))
